// spec: specs/warehouse-map.md §6 · кейс .qa/tests/warehouse-map/wm-01-assigned-location-not-empty.md (п. 4–9)
// seed: tests/seed.admin.spec.ts
// #d9258e0b (fix реджекта 30fbd2fc на #6a8f3153): товар с остатком 0, привязанный к месту, на карте не «ריק».
// Данные: QA-AUTO-wm01-<ts> (остаток 0). Места выбираются во время прогона — только свободные («ריק»), шкафы A–D не трогаем
// (их используют параллельные проверки): полка в шкафу на «קומה 1» + элемент «ארגז אחד» на «קומה 1».
// afterAll: «הסרה מהמקום» на обоих местах, удаление товара, проверка что оба места снова «ריק».
import { test, expect, Page, Browser } from '@playwright/test';
import { auth, side, openMap } from './_helpers';

const ADMIN = auth('admin');
test.use({ storageState: ADMIN });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const P = `QA-AUTO-wm01-${TS}`;
const FLOOR = 'קומה 1';
const FILL_OCCUPIED = '#e4ecf7';
const FILL_EMPTY = '#ffffff';

type Shelf = { cabinet: string; name: string; code: string };
type Box = { element: string; name: string; code: string };
let shelf: Shelf | undefined;
let box: Box | undefined;
let productCreated = false;

// ---------- каталог ----------
const qtyBtn = (page: Page) => page.getByRole('button', { name: `קליטת מלאי — ${P}`, exact: true });
const locBtn = (page: Page) => page.getByRole('button', { name: `מיקום במחסן — ${P}`, exact: true });
const row = (page: Page) => qtyBtn(page).locator('xpath=ancestor::*[.//button[@aria-label="פעולות"]][1]');

async function findProduct(page: Page) {
  await page.goto('/catalog');
  await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(P);
  await expect(qtyBtn(page).or(page.getByText('לא נמצאו מוצרים התואמים לסינון'))).toBeVisible({ timeout: 20_000 });
}

async function createProduct(page: Page) {
  await page.goto('/catalog/new');
  await expect(page.getByRole('heading', { level: 1, name: 'מוצר חדש' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('textbox', { name: /שם מוצר/ }).fill(P);
  await page.getByRole('textbox', { name: /מק"ט/ }).fill(`QAWM01${TS}`);
  await page.getByRole('spinbutton', { name: 'מחיר בסיס' }).fill('1');
  productCreated = true;
  await page.getByRole('button', { name: 'שמירה', exact: true }).click();
  await expect(page.getByText('נוסף לקטלוג.')).toBeVisible({ timeout: 15_000 });
}

/** Окно «מיקום במחסן» / «הוספת מיקום» → «קומה 1» → элемент → полка/ארגז → «שמירה». */
async function bindInDialog(page: Page, add: boolean, element: string, target: string, code: string) {
  if (add) await row(page).getByText('הוספת מיקום').click();
  else await locBtn(page).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: add ? 'הוספת מיקום' : 'מיקום במחסן' })).toBeVisible();
  await expect(dlg).toContainText(P);
  await dlg.getByRole('tab', { name: FLOOR }).click();
  await expect(dlg.getByText('בחרו פריט אחסון')).toBeVisible();
  // элемент — первая кнопка с этим именем (список элементов), полка/ארגז — последняя (список внутри элемента)
  await dlg.getByRole('button', { name: element, exact: true }).first().click();
  await expect(dlg.getByText(new RegExp(`בחרו (מדף|ארגז) ב«${element}»`))).toBeVisible();
  await dlg.getByRole('button', { name: target, exact: true }).last().click();
  await expect(dlg).toContainText(`| ${code}`);
  await dlg.getByRole('button', { name: 'שמירה', exact: true }).click();
  await expect(dlg).toHaveCount(0, { timeout: 15_000 });
}

// ---------- карта ----------
const elementRow = (page: Page, element: string) =>
  side(page).getByRole('button', { name: new RegExp(`^${element} \\d+ `) }).first();
/** Строка места (полка/ארגז) в панели элемента: «<имя> <код> …». */
const placeRow = (page: Page, code: string) =>
  side(page).getByRole('button', { name: new RegExp(` ${code}(?![\\w-])`) }).first();
const placedItem = (page: Page) =>
  side(page).getByRole('listitem').filter({ hasText: P }).filter({ has: page.getByRole('button', { name: 'הסרה מהמקום' }) });
const shelfRect = (page: Page, s: Shelf) => page.locator(`svg rect[aria-label="${s.cabinet} · ${s.name}"]`);
const boxRect = (page: Page, b: Box) => page.locator(`svg rect[aria-label="${b.element}"]`);

async function loaded(page: Page) {
  await expect(page.getByText('טוען את המלאי')).toHaveCount(0, { timeout: 30_000 });
}

async function openElement(page: Page, element: string) {
  await openMap(page, FLOOR);
  await loaded(page);
  await elementRow(page, element).click();
  await expect(side(page).getByRole('heading', { name: /^תכולת / })).toBeVisible();
}

const lines = async (l: ReturnType<Page['locator']>) =>
  (await l.innerText()).split('\n').map((s) => s.trim()).filter(Boolean);

/** Свободная полка: шкаф на «קומה 1» (не A–D), строка шкафа «ריק»; полка «ריק» с уникальным в шкафу именем. Последняя подходящая. */
async function pickFreeShelf(page: Page): Promise<Shelf | undefined> {
  await openMap(page, FLOOR);
  await loaded(page);
  const cabinets = side(page).getByRole('button', { name: /^ארון (?![A-D] )\S+ 0 \d+ מדפים ריק$/ });
  const names = (await cabinets.allInnerTexts()).map((t) => t.split('\n')[0].trim()).reverse();
  for (const cabinet of names) {
    await elementRow(page, cabinet).click();
    await expect(side(page).getByRole('heading', { name: 'תכולת הארון' })).toBeVisible();
    const rows = side(page).getByRole('button', { name: / [A-Z]+-\d+ ריק$/ });
    const all = await Promise.all((await rows.all()).map(lines));
    const nameCount = new Map<string, number>();
    for (const [n] of all) nameCount.set(n, (nameCount.get(n) ?? 0) + 1);
    const free = all.filter(([n, c, e]) => e === 'ריק' && nameCount.get(n) === 1 && /^[A-Z]+-\d+$/.test(c)).reverse();
    if (free.length) return { cabinet, name: free[0][0], code: free[0][1] };
    await side(page).getByRole('button', { name: 'כל האחסון' }).click();
  }
  return undefined;
}

/** Свободный элемент «ארגז אחד» на «קומה 1» (строка «… 0 ארגז אחד ריק»), с уникальным именем на этаже. Последний подходящий. */
async function pickFreeBox(page: Page, avoid: string): Promise<Box | undefined> {
  await openMap(page, FLOOR);
  await loaded(page);
  const allNames = (await side(page).getByRole('button').allInnerTexts()).map((t) => t.split('\n')[0].trim());
  const rows = side(page).getByRole('button', { name: / 0 ארגז אחד ריק$/ });
  const names = (await rows.allInnerTexts()).map((t) => t.split('\n')[0].trim())
    .filter((n) => n !== avoid && allNames.filter((x) => x === n).length === 1).reverse();
  for (const element of names) {
    await elementRow(page, element).click();
    await expect(side(page).getByRole('heading', { name: /^תכולת / })).toBeVisible();
    const boxes = side(page).getByRole('button', { name: / [A-Z]+\d*-\d+ ריק$/ });
    if ((await boxes.count()) === 1) {
      const [name, code] = await lines(boxes.first());
      return { element, name, code };
    }
    await side(page).getByRole('button', { name: 'כל האחסון' }).click();
  }
  return undefined;
}

async function expectPlacedInPanel(page: Page) {
  const item = placedItem(page);
  await expect(item).toHaveCount(1);
  expect(await lines(item), 'количество товара в панели — 0').toContain('0');
  await expect(item.getByRole('button', { name: 'העברה למיקום אחר' })).toBeVisible();
  await expect(item.getByRole('button', { name: 'הסרה מהמקום' })).toBeVisible();
}

async function unplace(page: Page, element: string, code: string) {
  await openElement(page, element);
  await placeRow(page, code).click();
  if (!(await placedItem(page).count())) return;
  await placedItem(page).getByRole('button', { name: 'הסרה מהמקום' }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'הסרת המוצר מהמקום' })).toBeVisible();
  await dlg.getByRole('button', { name: 'הסרה', exact: true }).click();
  await expect(placedItem(page)).toHaveCount(0, { timeout: 15_000 });
}

async function deleteProduct(page: Page) {
  await findProduct(page);
  if (!(await qtyBtn(page).count())) return;
  await row(page).getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: /^מחיקה/ }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'מחיקת מוצר' })).toBeVisible({ timeout: 20_000 });
  await dlg.getByRole('button', { name: 'מחיקה', exact: true }).click();
  await expect(page.getByText(/הוסר מהקטלוג|נמחק\./).first()).toBeVisible({ timeout: 15_000 });
}

async function cleanupAll(browser: Browser) {
  const ctx = await browser.newContext({ storageState: ADMIN, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  try {
    if (shelf) await unplace(page, shelf.cabinet, shelf.code);
    if (box) await unplace(page, box.element, box.code);
    if (productCreated) await deleteProduct(page);
    if (shelf) {
      await openElement(page, shelf.cabinet);
      await expect(placeRow(page, shelf.code), `${shelf.code} после уборки — «ריק»`).toHaveAccessibleName(/ריק$/);
    }
    if (box) {
      await openElement(page, box.element);
      await expect(placeRow(page, box.code), `${box.code} после уборки — «ריק»`).toHaveAccessibleName(/ריק$/);
    }
  } finally {
    await ctx.close();
  }
}

test.describe('warehouse-map — מקום משויך למוצר עם מלאי 0 לא «ריק» (#d9258e0b)', () => {
  test.afterAll(async ({ browser }) => {
    test.setTimeout(240_000);
    await cleanupAll(browser);
  });

  test('שיוך בקטלוג למדף + «הוספת מיקום» לארגז — מוצר עם 0 #d9258e0b @desktop @data', async ({ page }) => {
    test.setTimeout(180_000);
    shelf = await pickFreeShelf(page);
    test.skip(!shelf, 'нет свободной полки в шкафу (не A–D) на «קומה 1»');
    box = await pickFreeBox(page, shelf!.cabinet);
    test.skip(!box, 'нет свободного элемента «ארגז אחד» на «קומה 1»');
    // до привязки места пустые: заливка #ffffff
    await openMap(page, FLOOR);
    await loaded(page);
    await expect(shelfRect(page, shelf!)).toHaveAttribute('fill', FILL_EMPTY);
    await expect(boxRect(page, box!).first()).toHaveAttribute('fill', FILL_EMPTY);

    await createProduct(page);
    await findProduct(page);
    await expect(qtyBtn(page)).toHaveText('0');
    await expect(locBtn(page)).toContainText('ללא מיקום');

    await bindInDialog(page, false, shelf!.cabinet, shelf!.name, shelf!.code);
    await findProduct(page);
    await expect(locBtn(page)).toContainText(shelf!.code);

    await bindInDialog(page, true, box!.element, box!.name, box!.code);
    await expect(page.getByText(/שויך למקום נוסף/).first()).toBeVisible({ timeout: 15_000 });
    await findProduct(page);
    await expect(qtyBtn(page)).toHaveText('0');
  });

  test('מפת המחסן: המדף והארגז תפוסים, לא «ריק»; במפקח — המוצר עם 0 (גם אחרי רענון ו־390) #d9258e0b @desktop', async ({ page }) => {
    test.setTimeout(180_000);
    test.skip(!shelf || !box, 'нет данных из предыдущего шага');
    const s = shelf!, b = box!;
    for (const pass of ['first', 'reload'] as const) {
      if (pass === 'reload') await page.reload();
      await openMap(page, FLOOR);
      await loaded(page);
      // сайдбар: строки элементов — «מוצר אחד משויך», не «ריק»
      await expect(elementRow(page, s.cabinet)).toHaveAccessibleName(new RegExp(`^${s.cabinet} 0 \\d+ מדפים מוצר אחד משויך$`));
      await expect(elementRow(page, b.element)).toHaveAccessibleName(new RegExp(`^${b.element} 0 ארגז אחד מוצר אחד משויך$`));
      // канвас: занятое — #e4ecf7
      await expect(shelfRect(page, s)).toHaveAttribute('fill', FILL_OCCUPIED);
      await expect(boxRect(page, b).first()).toHaveAttribute('fill', FILL_OCCUPIED);

      // полка: строка «<имя> <код> 0» без «ריק», инспектор — товар, «0», кнопки
      await elementRow(page, s.cabinet).click();
      await expect(side(page).getByRole('heading', { name: 'תכולת הארון' })).toBeVisible();
      await expect(placeRow(page, s.code)).toHaveAccessibleName(`${s.name} ${s.code} 0`);
      await placeRow(page, s.code).click();
      await expectPlacedInPanel(page);

      // ארגז: строка без «ריק», инспектор — товар, «0», кнопки
      await openMap(page, FLOOR);
      await loaded(page);
      await elementRow(page, b.element).click();
      await expect(placeRow(page, b.code)).not.toHaveAccessibleName(/ריק$/);
      await placeRow(page, b.code).click();
      await expectPlacedInPanel(page);
    }

    // телефон 390×844: на канвасе оба места закрашены как занятые
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('/warehouse/map');
    await expect(page.getByText(FLOOR).first()).toBeVisible({ timeout: 30_000 });
    await expect(shelfRect(page, s)).toHaveAttribute('fill', FILL_OCCUPIED, { timeout: 30_000 });
    await expect(boxRect(page, b).first()).toHaveAttribute('fill', FILL_OCCUPIED);
  });

  test('«הסרה מהמקום» — המדף שוב «ריק» (#ffffff), גם אחרי רענון; הארגז נשאר תפוס; בקטלוג בלי «קבוע» #d9258e0b @desktop @data', async ({ page }) => {
    test.setTimeout(180_000);
    test.skip(!shelf || !box, 'нет данных из предыдущего шага');
    const s = shelf!, b = box!;
    await unplace(page, s.cabinet, s.code);
    await expect(side(page).getByText('המדף ריק')).toBeVisible();
    await expect(shelfRect(page, s)).toHaveAttribute('fill', FILL_EMPTY);

    await page.reload();
    await openMap(page, FLOOR);
    await loaded(page);
    await expect(shelfRect(page, s)).toHaveAttribute('fill', FILL_EMPTY);
    await expect(boxRect(page, b).first()).toHaveAttribute('fill', FILL_OCCUPIED);
    await expect(elementRow(page, s.cabinet)).toHaveAccessibleName(/ריק$/);
    await expect(elementRow(page, b.element)).toHaveAccessibleName(/מוצר אחד משויך$/);
    await elementRow(page, s.cabinet).click();
    await expect(placeRow(page, s.code)).toHaveAccessibleName(/ריק$/);

    await findProduct(page);
    await expect(locBtn(page)).not.toContainText('קבוע');
    await expect(row(page).getByText('קבוע', { exact: true })).toHaveCount(0);
  });
});
